  'physics-waves-sound': [
    { text: "Moving back and forth regularly between two points.", author: "oscillate" },
    { text: "A disturbance that moves from its source and carries energy.", author: "wave" },
    { text: "Potential energy stored as a result of deformation of an elastic object, such as the stretching of a spring.", author: "elastic potential energy" },
    { text: "A constant related to the rigidity of a system. The larger the force constant, the more rigid the system, the force constant is represented by k.", author: "force constant" },
    { text: "Force acting in opposition to the force caused by a deformation.", author: "restoring force" },
    { text: "Time it takes to complete one oscillation.", author: "period" },
    { text: "Motion that repeats itself at regular time intervals.", author: "periodic motion" },
    { text: "Number of events per unit of time.", author: "frequency" },
    { text: "The maximum displacement from the equilibrium position of an object oscillating around the equilibrium position.", author: "amplitude" },
    { text: "The oscillatory motion in a system where the net force can be described by Hooke's law.", author: "simple harmonic motion" },
    { text: "A device that implements Hooke's law, such as a mass that is attached to a spring, with the other end of the spring being connected to a rigid support such as a wall.", author: "simple harmonic oscillator" },
    { text: "An object with a small mass suspended from a light wire or string.", author: "simple pendulum" },
    { text: "The condition in which the damping of an oscillator causes it to return as quickly as possible to its equilibrium position without oscillating back and forth about this position.", author: "critical damping" },
    { text: "The condition in which damping of an oscillator causes it to return to equilibrium without oscillating, oscillator moves more slowly toward equilibrium than in the critically damped system.", author: "over damping" },
    { text: "The condition in which damping of an oscillator causes it to return to equilibrium with the amplitude gradually decreasing to zero, system returns to equilibrium faster but overshoots and crosses the equilibrium position one or more times.", author: "under damping" },
    { text: "The frequency at which a system would oscillate if there were no driving and no damping forces.", author: "natural frequency" },
    { text: "A system being driven at its natural frequency.", author: "resonate" },
    { text: "A wave in which the disturbance is parallel to the direction of propagation.", author: "longitudinal wave" },
    { text: "A wave in which the disturbance is perpendicular to the direction of propagation.", author: "transverse wave" },
    { text: "The speed at which the disturbance moves. Also called the propagation velocity or propagation speed.", author: "wave velocity" },
    { text: "The distance between adjacent identical parts of a wave.", author: "wavelength" },
    { text: "The location of maximum amplitude in standing waves.", author: "antinode" },
    { text: "The frequency of the amplitude fluctuations of a wave.", author: "beat frequency" },
    { text: "When two waves arrive at the same point exactly in phase, that is, the crests of the two waves are precisely aligned, as are the troughs.", author: "constructive interference" },
    { text: "When two identical waves arrive at the same point exactly out of phase, that is, precisely aligned crest to trough.", author: "destructive interference" },
    { text: "The lowest frequency of a periodic waveform.", author: "fundamental frequency" },
    { text: "The points where the string does not move, more generally, nodes are where the wave disturbance is zero in a standing wave.", author: "nodes" },
    { text: "Multiples of the fundamental frequency of a sound.", author: "overtones" },
    { text: "The phenomenon that occurs when two or more waves arrive at the same point.", author: "superposition" },
    { text: "A disturbance of matter that is transmitted from its source outward.", author: "sound" },
    { text: "The power per unit area carried by a wave.", author: "intensity" },
    { text: "A unitless quantity telling you the level of the sound relative to a fixed standard.", author: "sound intensity level" },
    { text: "The ratio of the pressure amplitude to a reference pressure.", author: "sound pressure level" },
    { text: "An alteration in the observed frequency of a sound due to motion of either the source or the observer.", author: "Doppler effect" },
    { text: "The actual change in frequency due to relative motion of source and observer.", author: "Doppler shift" },
    { text: "A constructive interference of sound created by an object moving faster than sound.", author: "sonic boom" },
    { text: "V-shaped disturbance created when the wave source moves faster than the wave propagation speed.", author: "bow wake" },
    { text: "The term used to refer collectively to the fundamental and its overtones.", author: "harmonics" },
    { text: "Basic unit of music with specific names, combined to generate tunes.", author: "note" },
    { text: "Number and relative intensity of multiple sound frequencies.", author: "tone" },
    { text: "Property of medium that makes the propagation of sound waves more difficult.", author: "acoustic impedance" },
    { text: "A measure of the ratio of the intensity of the wave reflected off a boundary between two media relative to the intensity of the incident wave.", author: "intensity reflection coefficient" },
    { text: "A medical technique to detect motion and determine velocity through the Doppler shift of an echo.", author: "Doppler-shifted ultrasound" },
  ],

