/**
 * Returns core subjects (tracks) that have active playable content authored in QUOTE_DB.
 */
export const getMasterableCoreTracks = (): Track[] =>
  SUBJECTS.filter(s =>
    BRANCHES.filter(b => b.tracks.includes(s.id)).some(b => (QUOTE_DB[b.id]?.length ?? 0) > 0)
  );

